package com.example.g.fragments;import android.os.Bundle;import android.view.*;import android.widget.TextView;import androidx.annotation.*;import androidx.fragment.app.Fragment;import com.example.g.R;public class MessageFragment extends Fragment{public MessageFragment(){super(R.layout.fragment_message);}public static MessageFragment make(String t,String m){MessageFragment f=new MessageFragment();Bundle b=new Bundle();b.putString("t",t);b.putString("m",m);f.setArguments(b);return f;}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle b){TextView t=v.findViewById(R.id.title),m=v.findViewById(R.id.message);t.setText(requireArguments().getString("t"));m.setText(requireArguments().getString("m"));}}
